private final int[] table = buildTable();

private int[] buildTable() {
    int[] t = new int[256];
    for (int b = 0; b < 256; b++) {
        int rev = 0, x = b;
        for (int i = 0; i < 8; i++) {
            rev = (rev << 1) | (x & 1);
            x >>= 1;
        }
        t[b] = rev;
    }
    return t;
}

public int reverseBits(int n) {
    int result = 0;
    for (int i = 0; i < 4; i++) {
        int b = (n >>> (8 * i)) & 0xFF;
        result |= table[b] << (8 * (3 - i));
    }
    return result;
}

code.python:
def reverseBits(self, n: int) -> int:
    if not hasattr(self, '_table'):
        self._table = [self._reverse_byte(b) for b in range(256)]
    result = 0
    for i in range(4):
        b = (n >> (8 * i)) & 0xFF
        result |= self._table[b] << (8 * (3 - i))
    return result & 0xFFFFFFFF

def _reverse_byte(self, b: int) -> int:
    rev = 0
    for _ in range(8):
        rev = (rev << 1) | (b & 1)
        b >>= 1
    return rev

